#!/usr/bin/env python3
# Auto-generated embedded migration — run once on server:
#   cd /opt/teklif-sistemi && source venv/bin/activate && python3 migrate_embedded.py

import sqlite3, json, datetime, os, base64

_DATA_B64 = ""

def main():
    os.makedirs("data", exist_ok=True)
    import db.factory as fdb
    import db.users as udb
    fdb.init(); udb.init()

    d = json.loads(base64.b64decode(_DATA_B64).decode("utf-8"))
    USERS = d["users"]; CATS = d["cats"]; OPTS = d["opts"]
    MODS  = d["mods"];  CUSTS= d["custs"]; OFFS = d["offs"]; ITEMS = d["items"]

    dst_u = sqlite3.connect("data/users.db")
    dst_f = sqlite3.connect("data/factory.db")

    # ── Users ─────────────────────────────────────────────────────
    print("[1/5] Users...")
    dst_u.execute("DELETE FROM users")
    for u in USERS:
        role = u.get("role","dealer")
        if role not in ("admin","manufacturer","dealer"): role = "dealer"
        dst_u.execute("""
            INSERT OR REPLACE INTO users
            (id,email,password,company_name,role,user_type,is_approved,is_active,
             phone,logo_path,website,address,allowed_categories,can_view_costs,lang,theme)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (
            u["id"], u["email"], u["password"],
            u.get("company_name") or "",
            role, role,
            int(u.get("is_approved") or 0), 1,
            u.get("phone") or "",
            u.get("logo_path") or "",
            u.get("website") or "",
            u.get("address_full") or u.get("address") or "",
            u.get("allowed_categories") or "",
            int(u.get("can_view_costs") or 0),
            u.get("preferred_lang") or "tr",
            "dark",
        ))
    dst_u.execute("UPDATE sqlite_sequence SET seq=? WHERE name='users'",
                  (max(u["id"] for u in USERS),))
    dst_u.commit()
    print(f"  ✓ {len(USERS)} users")
    for u in USERS:
        print(f"    [{u.get('role','?'): <12}] {u['email']} — {u.get('company_name','')}")

    # ── Categories ────────────────────────────────────────────────
    print("[2/5] Categories...")
    dst_f.execute("DELETE FROM categories")
    cat_map = {}
    for c in CATS:
        dst_f.execute("INSERT OR REPLACE INTO categories(id,name) VALUES(?,?)",(c["id"],c["name"]))
        cat_map[c["name"]] = c["id"]
    dst_f.execute("UPDATE sqlite_sequence SET seq=? WHERE name='categories'",
                  (max(c["id"] for c in CATS),))
    dst_f.commit()
    print(f"  ✓ {len(CATS)} categories: {[c['name'] for c in CATS]}")

    # ── Options ───────────────────────────────────────────────────
    print("[3/5] Options...")
    dst_f.execute("DELETE FROM options")
    for o in OPTS:
        cat_id   = cat_map.get(o.get("category") or "")
        qty_type = "MANUAL" if o.get("allow_qty") else "FIXED_1"
        scope    = "MODEL_SPECIFIC" if (o.get("usage_scope") or "") == "specific" else "GLOBAL"
        dst_f.execute("""
            INSERT OR REPLACE INTO options
            (id,name,description,price,currency,scope,category_id,qty_type,conflict_group)
            VALUES(?,?,?,?,?,?,?,?,?)
        """,(o["id"], o.get("opt_name") or "", o.get("opt_desc") or "",
             float(o.get("opt_price") or 0), o.get("currency") or "USD",
             scope, cat_id, qty_type, o.get("conflict_feature") or ""))
    dst_f.execute("UPDATE sqlite_sequence SET seq=? WHERE name='options'",
                  (max(o["id"] for o in OPTS),))
    dst_f.commit()
    print(f"  ✓ {len(OPTS)} options")

    # ── Models ────────────────────────────────────────────────────
    print("[4/5] Models...")
    dst_f.execute("DELETE FROM models")
    for m in MODS:
        cat_id = cat_map.get(m.get("category") or "")
        compat_raw = m.get("compatible_options") or ""
        try:
            compat = json.dumps([int(x.strip()) for x in compat_raw.split(",") if x.strip().isdigit()])
        except Exception:
            compat = "[]"
        pp=float(m.get("purchase_price") or 0); sc=float(m.get("shipping_cost") or 0)
        cust_r=float(m.get("customs_tax_rate") or 0); ext=float(m.get("extra_tax_rate") or 0)
        port=float(m.get("port_cost") or 0); doc=float(m.get("document_cost") or 0)
        inst=float(m.get("installation_cost") or 0); othr=float(m.get("other_cost") or 0)
        total_cost = pp+sc+pp*cust_r/100+pp*ext/100+port+doc+inst+othr
        dst_f.execute("""
            INSERT OR REPLACE INTO models
            (id,name,category_id,description,base_price,currency,specs,
             purchase_price,purchase_currency,shipping_cost,customs_pct,extra_tax_pct,
             port_cost,document_cost,installation_cost,other_cost,total_cost,
             image_path,compatible_options)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """,(m["id"], m.get("name") or "", cat_id, "",
             float(m.get("base_price") or 0), m.get("currency") or "USD",
             m.get("specs") or "", pp,"USD",sc,cust_r,ext,port,doc,inst,othr,total_cost,
             "", compat))
    dst_f.execute("UPDATE sqlite_sequence SET seq=? WHERE name='models'",
                  (max(m["id"] for m in MODS),))
    dst_f.commit()
    print(f"  ✓ {len(MODS)} models:")
    for m in MODS:
        print(f"    [{m['id']}] {m['name']} — {m.get('base_price',0)} {m.get('currency','USD')}")

    # ── Customers & Offers ────────────────────────────────────────
    print("[5/5] Customers & Offers...")
    dst_f.execute("DELETE FROM customers")
    dst_f.execute("DELETE FROM offers")
    dst_f.execute("DELETE FROM offer_items")

    real_custs = [c for c in CUSTS if (c.get("company_name") or "").strip() not in ("","Test")]
    for c in real_custs:
        dst_f.execute(
            "INSERT OR REPLACE INTO customers(id,name,contact_person,email,phone,address) VALUES(?,?,?,?,?,?)",
            (c["id"], c.get("company_name") or "", c.get("contact_person") or "",
             c.get("email") or "", c.get("phone") or "", c.get("address") or ""))
    if real_custs:
        dst_f.execute("UPDATE sqlite_sequence SET seq=? WHERE name='customers'",
                      (max(c["id"] for c in real_custs),))

    mod_map = {m["id"]: m for m in MODS}
    for o in OFFS:
        raw_date = o.get("offer_date") or ""
        try: created_at = datetime.datetime.strptime(raw_date,"%d.%m.%Y %H:%M").strftime("%Y-%m-%d %H:%M:%S")
        except Exception: created_at = raw_date
        try: cond = json.loads(o.get("conditions") or "{}")
        except Exception: cond = {}
        disc  = float(cond.get("discount_pct") or 0)
        mod   = mod_map.get(o.get("model_id") or 0, {})
        base  = float(mod.get("base_price") or 0)
        cur   = mod.get("currency") or "USD"
        sub   = float(cond.get("subtotal_calculated") or o.get("total_price") or 0)
        opts_t= max(0.0, sub - base)
        datep = created_at[:10].replace("-","") if len(created_at) >= 10 else "00000000"
        offer_no = f"TKL-{datep}-{o['id']:03d}"
        notes = "\n".join(filter(None,[o.get("notes") or "", cond.get("notes") or ""]))
        dst_f.execute("""
            INSERT OR REPLACE INTO offers
            (id,offer_no,customer_id,model_id,machine_count,currency,
             base_price,options_total,discount_pct,total_price,
             status,notes,validity_date,dealer_id,created_at)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """,(o["id"], offer_no, o.get("customer_id"), o.get("model_id"),
             1, cur, base, opts_t, disc,
             float(o.get("total_price") or 0),
             o.get("status") or "Beklemede", notes, "",
             o.get("user_id"), created_at))
    for it in ITEMS:
        dst_f.execute(
            "INSERT OR REPLACE INTO offer_items(id,offer_id,option_id,qty,unit_price,line_total) VALUES(?,?,?,?,?,?)",
            (it["id"],it["offer_id"],it["option_id"],it.get("quantity") or 1,0,0))
    if OFFS:
        dst_f.execute("UPDATE sqlite_sequence SET seq=? WHERE name='offers'",
                      (max(o["id"] for o in OFFS),))
    dst_f.commit()
    print(f"  ✓ {len(real_custs)} customers, {len(OFFS)} offers, {len(ITEMS)} offer items")

    dst_u.close(); dst_f.close()
    print()
    print("=" * 52)
    print("✅  Migration complete!")
    print("    Run: systemctl restart ersanb2b")
    print("=" * 52)

if __name__ == "__main__":
    main()
